testo:
{
 "genere": "prevedi",
 "titolo": "Cosa restituisce?",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted

enum State { IDLE, RUN, JUMP }


func run():
	var current_state := State.RUN
	var speed := 160.0
	if current_state == State.RUN:
		speed *= 2.0
	return speed
",
   "domanda": "Quanto vale `speed` alla fine?",
   "spiegazione": "`current_state` è uguale a `State.RUN`, quindi la condizione `if` è vera. La velocità viene moltiplicata per 2.0, passando da 160.0 a 320.0."
  },
  {
   "codice": "extends RefCounted


func run():
	var velocity_y := -150.0
	var state := ""
	if velocity_y < 0.0:
		state = "jump"
	else:
		state = "fall"
	return state
",
   "domanda": "Che testo restituisce `run()`?",
   "spiegazione": "`velocity_y` è -150.0, che è minore di 0.0. La condizione è vera e assegna la stringa "jump" a `state`."
  },
  {
   "codice": "extends RefCounted


func run():
	var has_dash := true
	var is_dashing := false
	if has_dash and not is_dashing:
		is_dashing = true
		has_dash = false
	return has_dash
",
   "domanda": "Quanto vale `has_dash` alla fine?",
   "spiegazione": "La condizione `has_dash and not is_dashing` è vera perché `has_dash` è true e `is_dashing` è false (quindi `not is_dashing` è true). Dentro il blocco, `has_dash` viene impostato a false."
  },
  {
   "codice": "extends RefCounted


func run():
	var velocity := Vector2(0, 0)
	var dash_speed := 400.0
	var direction := -1.0
	velocity.x = direction * dash_speed
	return velocity
",
   "domanda": "Che Vector2 restituisce `run()`?",
   "spiegazione": "`velocity.x` viene calcolato come `-1.0 * 400.0`, cioè `-400.0`. La componente y rimane a 0, quindi il risultato è `Vector2(-400, 0)`."
  },
  {
   "codice": "extends RefCounted


func run():
	var coyote_timer := 0.15
	var delta := 0.05
	coyote_timer -= delta
	coyote_timer -= delta
	return coyote_timer
",
   "domanda": "Quanto vale `coyote_timer` alla fine?",
   "spiegazione": "`coyote_timer` parte da 0.15. Sottraendo `delta` (0.05) due volte si tolgono in totale 0.10, lasciando 0.05."
  }
 ]
}
